import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop, State } from '@stencil/core';
import { FormDataEvent, FormSize, LabelPosition } from '../../types';

/**
 * @nativeEvent click - dispatched when switch was clicked => 'event.target.checked' delivers the current state
 * @nativeEvent change - dispatched when switch state has changed => 'event.target.checked' delivers the current state
 * @slot default - default slot for the label of the switch
 */
@Component({
  tag: 'groupui-switch',
  styleUrl: 'switch.scss',
  shadow: true,
})
export class Switch {
  /**
   * checked status of the switch
   */
  @Prop({ reflect: true, mutable: true }) checked: boolean = false;

  /**
   * deactivates the switch
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * name of the switch component to support forms
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * value part of the name/value pair associated with this element for the purposes of form submission.
   */
  @Prop({ reflect: true }) readonly value: string = 'on';

  /**
   * sets focus automatically
   */
  @Prop({ reflect: true }) readonly autofocus: boolean;

  /**
   * position of the label
   */
  @Prop({ reflect: true }) readonly labelPosition: LabelPosition = 'right';

  /**
   * sets the size of the switch
   */
  @Prop({ reflect: true }) readonly size: FormSize = 'm';

  /**
   * when enabled, displays an icon inside the switch toggle to improve visibility for color blind users
   */
  @Prop({ reflect: true }) readonly indicator: boolean = false;

  /**
   * for react user only - use this instead of the native change event
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  @State() switchTabIndex: number = 0;

  @Listen('click', { capture: true })
  onClick(event) {
    if (this.disabled) {
      event.stopImmediatePropagation();
    }
  }

  @Listen('click')
  handleClick() {
    if (this.disabled) {
      return;
    }

    this.checked = !this.checked;
    this.host.dispatchEvent(new window.Event('change'));
    this.groupuiChange.emit();
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (event.code === 'Space') {
      event.preventDefault();
    }
  }

  @Listen('keyup')
  onKeyUp(event: KeyboardEvent) {
    if (event.code === 'Space') {
      this.handleClick();
    }
  }

  componentWillLoad() {
    this.handleHostTabIndex();
    this.initFormsHandling();
  }

  componentDidLoad() {
    this.autofocus && this.host.focus && this.host.focus();
    this.groupuiDidLoad.emit();
  }

  private initFormsHandling() {
    if (this.name === undefined) return;

    const form = this.host.closest('form');
    if (form == null) return;

    form.addEventListener('formdata', (event: FormDataEvent) => {
      if (this.checked) {
        event.formData.append(this.name, this.value);
      }
    });
  }

  private handleHostTabIndex = () => {
    const tabIndex = this.host.getAttribute('tabIndex');
    if (tabIndex) {
      this.host.removeAttribute('tabIndex');
      this.switchTabIndex = Number(tabIndex);
    }

    if (this.disabled) {
      this.switchTabIndex = -1;
    }
  };

  private slotContainsText() {
    return this.host.textContent.trim().length > 0;
  }

  private getLabel() {
    return (
      this.slotContainsText() && (
        <div id="label" aria-disabled={this.disabled ? 'true' : null}>
          <slot />
        </div>
      )
    );
  }

  render() {
    return (
      <Host tabIndex={this.disabled ? -1 : 0} role="switch" aria-checked={this.checked ? 'true' : 'false'}>
        {this.labelPosition === 'left' && this.getLabel()}
        <div id="container">
          <div id="toggle">
            {this.indicator && (
              <groupui-icon
                aria-hidden="true"
                name={this.checked ? 'check-16' : 'line-horizontal-16'}
                id="indicator-icon"
              />
            )}
          </div>
        </div>
        {this.labelPosition === 'right' && this.getLabel()}
      </Host>
    );
  }
}
